# Notes pédagogiques retrouvées et générateur adapté ; voir PROVENANCE.md.
from docx import Document
from docx.shared import Pt, Cm
from docx.enum.text import WD_PARAGRAPH_ALIGNMENT

import argparse
from pathlib import Path
parser=argparse.ArgumentParser(description='Générer des notes ITIL pédagogiques adaptées.')
parser.add_argument('--output',required=True,type=Path)
args=parser.parse_args()
args.output.parent.mkdir(parents=True,exist_ok=True)
out=str(args.output)
doc=Document()
for s in doc.sections:
    s.top_margin=Cm(1.8); s.bottom_margin=Cm(1.8); s.left_margin=Cm(2.0); s.right_margin=Cm(2.0)
styles=doc.styles
styles['Normal'].font.name='Calibri'; styles['Normal'].font.size=Pt(10.5)
for name,size in [('Title',20),('Subtitle',11),('Heading 1',15),('Heading 2',12.5)]:
    styles[name].font.name='Calibri'; styles[name].font.size=Pt(size); styles[name].font.bold=True

def para(text):
    doc.add_paragraph(text)

def bullets(items):
    for it in items:
        doc.add_paragraph(it, style='List Bullet')

def numbers(items):
    for it in items:
        doc.add_paragraph(it, style='List Number')

def table(headers, rows):
    t=doc.add_table(rows=1, cols=len(headers)); t.style='Table Grid'
    for i,h in enumerate(headers): t.rows[0].cells[i].text=h
    for row in rows:
        cells=t.add_row().cells
        for i,v in enumerate(row): cells[i].text=str(v)
    doc.add_paragraph('')

p=doc.add_paragraph(style='Title'); p.alignment=WD_PARAGRAPH_ALIGNMENT.CENTER; p.add_run('ITIL – Fiche de révision détaillée')
p=doc.add_paragraph(style='Subtitle'); p.alignment=WD_PARAGRAPH_ALIGNMENT.CENTER; p.add_run('Incident Management, Change Management et Problem Management\nVersion entretien enrichie : réponses complètes, logique d’exploitation, exemples concrets et formulations professionnelles')
para("Objectif : vous aider à répondre en entretien avec une posture production/exploitation, en montrant à la fois la maîtrise des concepts ITIL, la capacité de diagnostic, la gestion du risque, la communication, l’escalade et l’amélioration continue. Ce document s’appuie sur votre support de préparation et l’enrichit avec des réponses plus complètes et plus réalistes pour l’oral.")

doc.add_heading('1. Vision d’ensemble : ce que le recruteur attend', level=1)
para("En entretien, un recruteur ne cherche pas seulement une définition théorique d’ITIL. Il veut surtout vérifier que vous savez appliquer ces principes dans un environnement réel de production.")
para("Ce qu’il attend généralement :")
bullets(["qualifier un incident et ne pas partir dans tous les sens ;","prioriser correctement selon l’impact métier et l’urgence réelle ;","faire un diagnostic initial utile sans perdre de temps ;","documenter et communiquer clairement ;","escalader au bon moment avec les bonnes informations ;","distinguer le traitement du symptôme, la gestion du changement et la recherche de cause racine ;","tirer un retour d’expérience pour éviter la répétition de l’incident."])
para("Une réponse mature en entretien suit souvent cette logique : qualification du sujet, sécurisation du périmètre, action immédiate adaptée, communication, traçabilité, puis amélioration durable.")

doc.add_heading('2. Incident Management', level=1)
para("Définition : un incident est toute interruption non planifiée d’un service IT ou toute dégradation de la qualité d’un service. Il peut être visible par les utilisateurs, détecté par la supervision ou remonté par une autre équipe.")
para("Objectif principal : rétablir le service normal le plus vite possible, avec un impact minimal sur les utilisateurs, les opérations et le métier.")
doc.add_heading('2.1 Ce qu’il faut vraiment comprendre', level=2)
bullets(["Un incident n’est pas forcément la cause profonde. C’est d’abord un symptôme, une panne, un ralentissement ou un comportement anormal qu’il faut traiter rapidement.","L’Incident Management privilégie le rétablissement du service. On peut donc accepter un contournement temporaire si cela permet de remettre les utilisateurs au travail rapidement, à condition que ce contournement soit maîtrisé et tracé.","Une mauvaise qualification au départ fait perdre un temps précieux : on mobilise les mauvaises équipes, on communique mal et on risque de dépasser les SLA.","Le bon réflexe est d’évaluer immédiatement le périmètre : qui est impacté, quel service est concerné, depuis quand, quel est l’effet métier, et s’il existe ou non une solution de contournement."])
doc.add_heading('2.2 Impact, urgence et priorité', level=2)
para("La priorité d’un incident repose généralement sur deux axes :")
bullets(["l’impact : ampleur de l’incident, population touchée, criticité du service, effet financier, réglementaire ou opérationnel ;","l’urgence : vitesse à laquelle il faut agir pour éviter que la situation ne s’aggrave ou pour respecter un engagement de service."])
para("Exemple : un service indisponible pour tout un périmètre métier critique en production sera prioritaire même si la cause n’est pas encore connue. À l’inverse, un incident isolé avec faible impact et contournement disponible sera traité avec une priorité moindre.")
table(['Impact','Urgence','Priorité','Exemple'],[['Élevé','Élevée','P1','Service de production critique indisponible pour tous les utilisateurs'],['Élevé','Moyenne','P2','Service majeur dégradé avec contournement partiel'],['Moyen','Élevée','P2','Équipe métier bloquée sur une application clé'],['Moyen','Moyenne','P3','Incident localisé avec impact modéré'],['Faible','Faible','P4','Incident mineur ou demande peu urgente']])
doc.add_heading('2.3 Étapes du processus incident', level=2)
numbers(["Identification et enregistrement : consigner les symptômes, l’heure de début, les erreurs visibles, le périmètre impacté, les utilisateurs concernés et le contexte de survenue.","Catégorisation et priorisation : rattacher l’incident à la bonne catégorie technique ou fonctionnelle et lui attribuer la priorité adaptée.","Diagnostic initial : lancer des vérifications rapides et pertinentes, par exemple service arrêté, saturation, logs, connectivité, dépendances, capacité, droits ou changement récent.","Escalade : transférer vers la bonne équipe quand le sujet dépasse le périmètre du niveau courant, quand le SLA est menacé ou quand l’incident exige des compétences ou des accès spécifiques.","Résolution et clôture : appliquer un correctif ou un contournement, valider le retour à la normale, documenter précisément ce qui a été fait et, si besoin, ouvrir un problème ou un changement associé."])
doc.add_heading('2.4 Quand et comment escalader', level=2)
para("Une escalade n’est pas un échec. C’est un acte de maîtrise. Le mauvais comportement est d’attendre trop longtemps, de continuer à tester au hasard, ou d’escalader sans résumé clair.")
bullets(["Escalade fonctionnelle : vers une équipe plus experte, par exemple N1 vers N2, N2 vers N3, base de données, réseau, sécurité, éditeur.","Escalade hiérarchique : quand il faut des arbitrages, une validation, des ressources supplémentaires ou une coordination renforcée.","Escalade fournisseur / éditeur : quand le sujet dépend d’un produit tiers, d’un bug applicatif, d’une licence, d’un correctif éditeur ou d’un équipement sous support."])
para("Une bonne escalade contient au minimum : le contexte, l’impact, les symptômes, les heures clés, les vérifications déjà faites, les résultats obtenus, les logs ou preuves utiles, et l’attente précise vis-à-vis de l’équipe destinataire.")
doc.add_heading('2.5 Réponse d’entretien complète – Incident critique', level=2)
para("Question : Que faites-vous lorsqu’un incident de production critique est déclaré ?")
para("Réponse modèle : lorsqu’un incident critique est déclaré, je commence par qualifier très rapidement le périmètre exact : quel service est touché, qui est impacté, depuis quand, et si l’impact est total ou partiel. Mon premier objectif est d’éviter la confusion et de disposer d’une vision claire de la situation. Ensuite, j’ouvre ou mets à jour le ticket avec les premières informations fiables, puis je lance un diagnostic initial court mais ciblé : disponibilité du service, connectivité, état des dépendances, logs récents, charge système, changements récents et alertes de supervision. Si je peux rétablir rapidement le service avec une action sûre, par exemple un redémarrage contrôlé, une relance de service ou un basculement prévu, je le fais. Si le sujet dépasse mon périmètre ou si le SLA est menacé, j’escalade immédiatement avec un résumé structuré. En parallèle, je communique régulièrement aux parties prenantes pour éviter le silence et maintenir une bonne coordination. Une fois le service rétabli, je documente précisément les actions menées, les causes probables et j’évalue s’il faut ouvrir un problème pour traiter la cause racine.")
doc.add_heading('2.6 Exemple concret adapté à votre expérience', level=2)
para("Exemple concret : dans un environnement de production critique, vous avez eu à gérer des anomalies de workflows, des ralentissements applicatifs, des échecs ponctuels sur des processus métiers sensibles, ainsi que des situations où certaines erreurs étaient liées à un changement de paramétrage ou à une dépendance externe. Dans ce type de contexte, votre posture ITIL consiste d’abord à rétablir le flux métier le plus vite possible, par exemple en identifiant le composant fautif, en isolant le périmètre, en vérifiant les logs et en confirmant si l’anomalie est généralisée ou limitée. Ensuite, vous structurez l’escalade vers l’équipe concernée – base de données, middleware, annuaire, applicatif ou infrastructure – avec les éléments déjà qualifiés. Cette manière de travailler montre que vous n’êtes pas seulement dans la réaction technique, mais dans la continuité de service, la traçabilité et la coordination inter-équipes.")

doc.add_heading('3. Change Management', level=1)
para("Définition : un changement est tout ajout, toute modification ou tout retrait d’un composant, d’une configuration, d’une infrastructure ou d’un service IT qui peut avoir un impact sur l’environnement. Contrairement à l’incident, le changement est une action volontaire, planifiée et contrôlée.")
para("Objectif principal : introduire les évolutions de façon maîtrisée, traçable et avec un niveau de risque acceptable, afin d’améliorer le service sans dégrader la production.")
doc.add_heading('3.1 Types de changements', level=2)
bullets(["Changement standard : changement répétitif, faible risque, préapprouvé, documenté et maîtrisé. Exemple : création d’un accès standard, redémarrage planifié encadré, opération récurrente d’exploitation.","Changement normal : changement nécessitant une analyse d’impact, une évaluation de risque, une validation et une planification. Exemple : mise à jour d’un serveur, modification DNS, changement de paramétrage applicatif, évolution d’architecture.","Changement d’urgence : changement exécuté rapidement pour corriger un incident majeur, une faille de sécurité ou une dégradation critique, tout en gardant un minimum de traçabilité et d’autorisation adaptée au contexte."])
doc.add_heading('3.2 Ce qu’un recruteur veut entendre', level=2)
bullets(["Vous ne changez pas un système sensible sans évaluer le risque.","Vous mesurez les dépendances : réseau, annuaire, base de données, application, sécurité, sauvegarde, supervision.","Vous prévoyez un rollback réaliste.","Vous communiquez avant, pendant et après l’intervention.","Vous vérifiez le résultat et vous ne fermez pas le changement trop tôt."])
doc.add_heading('3.3 Étapes d’un bon changement', level=2)
numbers(["Enregistrer la demande : quoi, pourquoi, quand, qui, prérequis, dépendances, impacts potentiels.","Analyser l’impact et le risque : risques techniques, métier, sécurité, indisponibilité, perte de données, régression, dépendances croisées.","Faire autoriser le changement : Change Manager, CAB ou circuit d’urgence selon le type et la criticité.","Implémenter dans une fenêtre adaptée : exécution selon le plan validé, avec communication aux parties prenantes.","Vérifier et clôturer : tests post-changement, surveillance renforcée, documentation des écarts, incidents éventuels et enseignements."])
doc.add_heading('3.4 Réponse d’entretien complète – Incident vs changement', level=2)
para("Question : Quelle différence entre un incident et un changement ?")
para("Réponse modèle : un incident est un événement subi que l’on doit traiter rapidement pour restaurer le service. Un changement est une action volontaire et contrôlée qui modifie l’environnement. Les deux peuvent être liés, par exemple lorsqu’un changement d’urgence est nécessaire pour résoudre un incident critique. Mais même dans ce cas, la logique n’est pas la même : l’incident pilote le rétablissement du service, tandis que le changement pilote la maîtrise du risque, la validation, la traçabilité et le retour arrière. En entretien, j’explique souvent qu’une organisation mature sait distinguer le moment où il faut agir vite pour restaurer et le moment où il faut sécuriser la modification pour ne pas créer un incident supplémentaire.")
doc.add_heading('3.5 Exemple concret adapté à votre expérience', level=2)
para("Exemple concret : dans vos activités d’exploitation, vous intervenez sur des plateformes où une modification apparemment simple peut avoir un impact large : ajustement de configuration, montée de version, modification de connectivité, traitement d’une licence, action sur un composant applicatif ou sur une base. Dans un tel contexte, une bonne approche ITIL consiste à préparer le changement avec un objectif précis, une fenêtre adaptée, un plan de vérification, une coordination avec les autres équipes et surtout un plan de retour arrière. Cela rejoint directement vos travaux de mise en production, vos procédures détaillées de réplication, vos changements liés à la haute disponibilité, ou encore vos interventions encadrées sur des composants critiques de plateforme. C’est un excellent point à valoriser en entretien, car cela démontre à la fois rigueur technique et discipline d’exploitation.")

doc.add_heading('4. Problem Management', level=1)
para("Définition : un problème est la cause sous-jacente d’un ou de plusieurs incidents. Là où l’Incident Management cherche à remettre le service en fonctionnement, le Problem Management cherche à comprendre pourquoi l’incident se produit et à éviter qu’il se reproduise.")
para("Objectif principal : identifier la cause racine, réduire la récurrence, capitaliser les connaissances et améliorer durablement la stabilité du service.")
doc.add_heading('4.1 Notions essentielles', level=2)
bullets(["Incident : symptôme ou interruption observée.","Problem : cause potentielle ou confirmée à l’origine d’incidents.","Known Error : problème dont la cause est connue et pour lequel un contournement ou un correctif a été documenté.","Proactive Problem Management : démarche consistant à analyser les tendances, les patterns et les faiblesses structurelles avant qu’elles ne provoquent une série d’incidents majeurs."])
doc.add_heading('4.2 Démarche d’investigation', level=2)
numbers(["Identifier les incidents répétitifs ou les anomalies récurrentes.","Ouvrir un ticket de problème distinct et le lier aux incidents concernés.","Constituer une chronologie claire des événements, changements récents, symptômes, logs et métriques.","Utiliser des méthodes structurées : 5 Why, Ishikawa, corrélation de logs, analyse de capacité, analyse des dépendances, tests ciblés.","Définir un contournement si nécessaire, puis un correctif durable.","Capitaliser : documenter la cause racine, les preuves, le workaround, la correction et les actions de prévention."])
doc.add_heading('4.3 Réponse d’entretien complète – gestion de problème', level=2)
para("Question : Quelle différence entre Incident Management et Problem Management ?")
para("Réponse modèle : l’Incident Management vise à restaurer rapidement le service, alors que le Problem Management vise à supprimer la cause racine pour éviter la répétition des incidents. En pratique, je considère souvent que l’incident traite l’urgence opérationnelle, alors que le problème traite la stabilité long terme. Par exemple, si une application tombe régulièrement en période de charge, l’incident peut consister à relancer le service ou à appliquer un contournement pour remettre les utilisateurs au travail. Le problème, lui, consistera à analyser les logs, la capacité, les dépendances et les changements récents pour comprendre si la vraie cause est une fuite mémoire, une saturation base, un défaut de configuration ou une limite d’architecture. Cette distinction est importante parce qu’une équipe qui ne traite que les incidents finit par vivre dans la répétition.")
doc.add_heading('4.4 Exemple concret adapté à votre expérience', level=2)
para("Exemple concret : vous avez déjà travaillé sur des analyses détaillées d’anomalies récurrentes, de blocages workflows, d’échecs applicatifs intermittents, de comportements dégradés liés à des erreurs de configuration, à des dépendances d’annuaire, à des problèmes de synchronisation ou à des incidents de base de données. Ce type de travail correspond directement au Problem Management. Vous ne vous contentez pas de constater une erreur ; vous collectez les journaux, vous identifiez les patterns, vous isolez les processus réellement anormaux, vous excluez les faux positifs, vous rapprochez l’événement d’un changement ou d’un comportement récurrent, puis vous proposez une action corrective ou une mesure préventive. C’est très fort en entretien parce que cela montre votre capacité à passer du support immédiat à l’analyse structurée et à l’amélioration continue.")

doc.add_heading('5. Escalade : bonnes pratiques opérationnelles', level=1)
para("L’escalade est un sujet très observé en entretien, car elle révèle votre maturité opérationnelle. Un bon candidat sait qu’il faut être autonome, mais aussi qu’il ne faut pas perdre du temps quand l’incident exige une expertise spécifique ou menace le SLA.")
bullets(["Escalader tôt vaut souvent mieux qu’escalader tard.","Une bonne escalade n’est pas une phrase vague du type 'ça ne marche pas'. Elle doit contenir des faits, des preuves et une attente précise.","Il faut distinguer escalade technique et escalade de gouvernance.","L’équipe qui reçoit l’escalade doit pouvoir reprendre rapidement sans refaire tout le diagnostic de base."])
para("Exemple de message d’escalade efficace : Incident P1 sur application critique depuis 09h15. Impact : tous les utilisateurs du périmètre Finance sont bloqués à la connexion. Vérifications effectuées : redémarrage contrôlé du service applicatif, test réseau concluant, logs applicatifs analysés, erreur de connexion base identifiée. Aucun changement déclaré sur l’application ce matin. Demande : prise en charge immédiate par l’équipe base de données pour investigation sur la disponibilité et l’intégrité des connexions.")

doc.add_heading('6. Questions / réponses d’entretien – version détaillée', level=1)
qas=[('Qu’est-ce qu’un incident ?','Un incident est toute interruption non planifiée d’un service IT ou toute dégradation de sa qualité. Cela peut aller d’une panne totale à un ralentissement important, en passant par un comportement anormal détecté par les utilisateurs ou la supervision. Ce qui compte en entretien, c’est de montrer que vous savez qu’un incident se traite d’abord sous l’angle du service rendu : qui est impacté, quel est l’effet métier, quelle est la priorité, et comment rétablir rapidement la situation.'),('Quel est l’objectif principal de l’Incident Management ?','L’objectif est de restaurer le service normal le plus vite possible avec un impact minimal pour les utilisateurs et le métier. Cela signifie que l’on ne cherche pas forcément à comprendre toute la cause profonde dans les premières minutes ; on cherche d’abord à remettre le service en état ou à fournir un contournement sûr. Ensuite seulement, si nécessaire, on ouvre une démarche de Problem Management pour traiter durablement la cause racine.'),('Comment déterminez-vous la priorité d’un incident ?','Je la détermine en croisant l’impact et l’urgence. L’impact mesure l’étendue réelle de l’incident : nombre d’utilisateurs touchés, criticité du service, conséquence métier, financière ou réglementaire. L’urgence mesure la vitesse à laquelle il faut agir pour éviter une aggravation ou une rupture prolongée. Cette priorisation doit être faite dès le départ, car elle conditionne les ressources mobilisées, le niveau de communication et les délais de traitement.'),('Quand faut-il escalader un incident ?','Il faut escalader lorsque les vérifications raisonnables de votre niveau ont été faites sans résultat, lorsque le sujet dépasse votre périmètre technique, lorsque le SLA est menacé, ou lorsque l’incident est critique et nécessite une action coordonnée. Pour moi, une escalade propre intervient assez tôt, avec un résumé structuré et utile, afin de ne pas perdre du temps en allers-retours.'),('Quelle différence entre une escalade fonctionnelle et hiérarchique ?','L’escalade fonctionnelle consiste à transférer le sujet vers une équipe plus experte ou mieux outillée, par exemple N2 vers N3, ou vers le réseau, la base de données, la sécurité ou l’éditeur. L’escalade hiérarchique, elle, vise à obtenir un arbitrage, des moyens supplémentaires, une validation particulière ou une coordination managériale plus forte. Les deux peuvent se compléter sur un incident majeur.'),('Qu’est-ce qu’un changement standard ?','C’est un changement répétitif, faible risque, bien documenté, avec une procédure connue et préapprouvée. Il est important de préciser en entretien qu’un changement standard n’est pas un changement improvisé ; au contraire, il est standard parce qu’il a déjà été évalué, encadré et validé comme peu risqué dans un contexte donné.'),('Quand parle-t-on de changement normal ou d’urgence ?','Le changement normal est celui qui demande une analyse d’impact, une évaluation de risque, des validations et une planification. Le changement d’urgence est réservé aux situations où il faut intervenir rapidement pour corriger un incident majeur ou une faille critique. Même en urgence, on garde un minimum de contrôle : autorisation adaptée, traçabilité, vérifications post-changement et idéalement rollback prévu.'),('Qu’est-ce qu’un problème en ITIL ?','Un problème est la cause sous-jacente d’un ou plusieurs incidents. En d’autres termes, l’incident est ce que l’on voit, le problème est ce qui l’explique en profondeur. Cette distinction est essentielle, car une organisation mature ne se contente pas de relancer des services à répétition ; elle cherche à supprimer ce qui provoque les incidents.'),('Qu’est-ce qu’un Known Error ?','Un Known Error est un problème dont la cause est connue et pour lequel un contournement ou un correctif a été documenté. C’est une notion importante parce qu’elle permet d’accélérer la prise en charge des incidents futurs en s’appuyant sur une connaissance déjà capitalisée.'),('Pourquoi faut-il séparer Incident Management et Problem Management ?','Parce qu’ils n’ont pas le même objectif. L’incident vise le rétablissement rapide du service ; le problème vise l’élimination durable de la cause racine. Si l’on mélange les deux, on risque soit d’être trop lent à restaurer le service, soit de ne jamais traiter le fond du sujet. La bonne pratique consiste donc à rétablir vite, puis à analyser proprement si l’incident est récurrent ou structurel.'),('Que doit contenir une bonne demande d’escalade ?','Une bonne demande d’escalade doit contenir le contexte, l’impact, les symptômes, les horaires utiles, les actions déjà tentées, les résultats obtenus, les preuves ou logs disponibles, ainsi que l’attente précise vis-à-vis de l’équipe sollicitée. Cela montre à la fois votre rigueur et votre respect du temps des autres équipes.'),('Que vérifiez-vous avant un changement en production ?','Je vérifie l’objectif, le périmètre, les dépendances, l’impact métier, le niveau de risque, les tests préalables, la fenêtre de mise en œuvre, la communication aux parties prenantes, et surtout le plan de retour arrière. Pour moi, un changement n’est pas prêt tant qu’on ne sait pas clairement comment revenir en arrière si le résultat n’est pas conforme.'),('Quelle erreur fréquente voyez-vous en gestion de changement ?','L’erreur la plus fréquente est de sous-estimer le risque ou les dépendances. Beaucoup d’incidents post-changement viennent d’un changement techniquement correct mais insuffisamment évalué dans son contexte global : horaires inadaptés, supervision oubliée, effet sur un composant dépendant, tests incomplets ou rollback irréaliste.')]
for q,a in qas:
    doc.add_heading(q, level=2); para(a)

doc.add_heading('7. Exemples de réponses concrètes en entretien, inspirées de votre activité', level=1)
for q,a in [('Parlez-nous d’une situation où vous avez géré un incident critique.','Dans mon activité d’exploitation, j’interviens sur des plateformes où certains incidents peuvent bloquer des processus métiers sensibles. Dans ce type de situation, ma première étape est toujours de qualifier le périmètre exact, d’identifier si l’incident est global ou localisé, puis de vérifier rapidement les composants critiques : disponibilité applicative, logs, connectivité, dépendances, état des services et changements récents. J’ai déjà eu à traiter des cas où des workflows échouaient de manière intermittente ou où un composant central présentait des signes de dégradation. Mon approche a consisté à stabiliser rapidement le service, à isoler les anomalies réellement bloquantes, à communiquer avec les équipes concernées et à formaliser les éléments utiles pour l’escalade. Ce que je retiens de ce type d’incident, c’est qu’il faut être à la fois rapide, méthodique et très clair dans la communication.'),('Donnez un exemple de changement sensible que vous avez préparé ou encadré.','J’ai eu à travailler sur des opérations sensibles liées à la haute disponibilité, à la réplication, à des mises en production encadrées et à des ajustements techniques sur des environnements critiques. Dans ce type de contexte, je ne me limite pas à l’action technique ; je prépare aussi la procédure, les prérequis, la fenêtre d’intervention, les points de contrôle, la coordination avec les parties prenantes et les conditions de retour arrière. Cela correspond parfaitement à une logique de Change Management : on ne cherche pas seulement à effectuer une modification, on cherche à la réussir avec un niveau de risque acceptable et une traçabilité suffisante.'),('Parlez-nous d’une analyse de cause racine que vous avez réalisée.','Une part importante de mon travail consiste justement à aller au-delà du symptôme. Par exemple, lorsqu’une erreur ou un blocage revient régulièrement, je cherche à distinguer les vrais incidents des faux positifs, à corréler les événements avec les logs, les changements récents, la volumétrie ou certains paramètres de configuration. J’ai déjà produit des analyses détaillées sur des anomalies intermittentes, des problèmes de synchronisation, des blocages de processus ou des échecs liés à des dépendances techniques. Cette démarche correspond au Problem Management : on structure les faits, on cherche les patterns, on documente la cause probable ou confirmée, puis on propose une remédiation durable ou au minimum un contournement stabilisé.')]:
    doc.add_heading(q, level=2); para(a)

doc.add_heading('8. Formulations fortes à utiliser à l’oral', level=1)
bullets(["Je commence toujours par qualifier précisément le périmètre, l’impact et l’urgence avant de lancer des actions.","Mon objectif est de rétablir le service rapidement, sans compromettre la stabilité du système.","Je documente les actions au fil de l’eau pour assurer la traçabilité et faciliter la reprise si une escalade est nécessaire.","Si le sujet sort de mon périmètre, j’escalade avec un résumé structuré des vérifications déjà faites.","Je distingue toujours le traitement immédiat du symptôme et l’analyse de la cause racine à plus long terme.","Pour un changement sensible, je sécurise le plan d’implémentation, les tests, la communication et le rollback."])
doc.add_heading('9. Mini check-list finale avant entretien', level=1)
bullets(["Savoir définir simplement incident, changement, problème et Known Error.","Être capable d’expliquer impact, urgence, priorité et SLA.","Préparer deux ou trois exemples concrets au format STAR.","Montrer que vous savez travailler avec d’autres équipes, documenter et escalader proprement.","Avoir un discours orienté continuité de service, risque maîtrisé et amélioration continue."])
para("Document enrichi à partir du support fourni par l’utilisateur, avec approfondissement des réponses et adaptation à une logique d’entretien orientée exploitation, production et coordination technique.")
doc.save(out)
print(out)
